package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamConstHistBank2 {
  private const val T = "ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ව්‍යවස්ථා පරිණාමය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාව බ්‍රිතාන්‍ය කිරීට යටත්විජිතයක් ලෙස ප්‍රකාශයට පත් වූ පසු පළමු බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා වූයේ කවුද?", "ෆ්‍රෙඩ්රික් නෝර්ත්", "රොබට් බ්‍රවුන්රිග්", "තෝමස් මෙට්ලන්ඩ්", "එඩ්වඩ් බාන්ස්", "1798 දී ෆ්‍රෙඩ්රික් නෝර්ත් මුහුදුබඩ පළාත්වල ප්‍රථම බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා ලෙස පත්විය."),
    q("උඩරට රාජධානිය බ්‍රිතාන්‍යයන්ට යටත් වන අවස්ථාවේ එහි ආණ්ඩුකාරවරයා ලෙස කටයුතු කළේ කවුද?", "රොබට් බ්‍රවුන්රිග්", "විලියම් හෝර්ටන්", "ජෝන් ඩොයිලි", "හෙන්රි වෝඩ්", "1815 උඩරට ගිවිසුම අත්සන් කිරීමේදී බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා වූයේ රොබට් බ්‍රවුන්රිග්ය."),
    q("1833 කෝල්බෲක් ප්‍රතිසංස්කරණ ක්‍රියාත්මක කිරීමේදී එවකට ලංකාවේ ආණ්ඩුකාරවරයා වශයෙන් සිටියේ කවුද?", "සර් රොබට් විල්මට් හෝර්ටන්", "සර් එඩ්වඩ් බාන්ස්", "හෙන්රි මැකලම්", "චාල්ස් මැකාති", "කෝල්බෲක්-කැමරන් යෝජනා 1833 දී ක්‍රියාවට නැංවූයේ ආණ්ඩුකාර හෝර්ටන්ගේ කාලයේය."),
    q("1833 ප්‍රතිසංස්කරණයෙන් පසු මුළු ලංකාව බෙදා වෙන් කරන ලද ප්‍රධාන පළාත් පහට අයත් නොවූ පළාත කුමක්ද?", "සබරගමුව පළාත", "බස්නාහිර පළාත", "මධ්‍යම පළාත", "උතුරු පළාත", "1833 දී බස්නාහිර, දකුණ, උතුර, නැගෙනහිර හා මධ්‍යම යන පළාත් 5 පිහිටුවන ලදී."),
    q("1833 විධායක සභාවේ සාමාජිකයන් පස්දෙනා කවුරුන්ගෙන් සමන්විත වීද?", "ආණ්ඩුකාරවරයා හා බ්‍රිතාන්‍ය ඉහළ නිලධාරීන් පිරිසකගෙන්", "ඡන්දයෙන් පත්වූ ලාංකික මන්ත්‍රීවරුන්ගෙන්", "ගම්සභා සභාපතිවරුන්ගෙන්", "පළාත් සභා ආණ්ඩුකාරවරුන්ගෙන්", "1833 විධායක සභාවට ලාංකික නියෝජිතයන් ඇතුළත් නොවූ අතර බ්‍රිතාන්‍ය නිලධාරීන් පමණක් සිටියහ."),
    q("1833 ව්‍යවස්ථාදායක සභාවේ සිටි නිල නොලත් මන්ත්‍රීවරුන් 6 දෙනා අතරින් යුරෝපීයයන් කී දෙනෙකු සිටියේද?", "3 දෙනෙකි", "1 දෙනෙකි", "5 දෙනෙකි", "6 දෙනෙකි", "නිල නොලත් 6 දෙනාගෙන් 3ක් යුරෝපීයයන්ටද, ඉතිරි 3 සිංහල, දෙමළ හා බර්ගර් ජනතාවටද වෙන් විය."),
    q("1889 වර්ෂයේදී ව්‍යවස්ථාදායක සභාවට අලුතින් එක් කරන ලද නියෝජිත ධුර දෙක කවර ජන කොටස් සඳහා වීද?", "උඩරට සිංහල හා මුස්ලිම් ප්‍රජාවන්", "ලන්දේසි හා පෘතුගීසි ප්‍රජාවන්", "යුරෝපීය හා ඉන්දීය වතු කම්කරුවන්", "මැලේ හා බර්ගර් ප්‍රජාවන්", "1889 දී ව්‍යවස්ථාදායක සභාව 17 දක්වා පුළුල් කරමින් උඩරට සිංහල හා මුස්ලිම් නියෝජන ලැබිණි."),
    q("1910 කෲව්-මැකලම් ප්‍රතිසංස්කරණ කාලයේ බ්‍රිතාන්‍ය යටත්විජිත ලේකම් හා ලංකාවේ ආණ්ඩුකාරවරයා වූයේ කවුද?", "ක්‍රූව් සාමි සහ සර් හෙන්රි මැකලම්", "ඩොනමෝර් සාමි සහ කෝල්බෲක්", "සෝල්බරි සාමි සහ චාල්ස් කැමරන්", "මැනිං ආණ්ඩුකාර හා මුවර්", "යටත්විජිත ලේකම් කෲව් සාමි හා ආණ්ඩුකාර හෙන්රි මැකලම්ගේ නමින් එම ව්‍යවස්ථාව හැඳින්විණි."),
    q("1910 කෲව්-මැකලම් ප්‍රතිසංස්කරණය යටතේ 'උගත් ලාංකික' අසුනට ඡන්දය දිය හැකි වූයේ මුළු ජනගහනයෙන් කුමන ප්‍රතිශතයකට පමණද?", "4% කටත් අඩු සුළු පිරිසකට", "50% කට වැඩි පිරිසකට", "75% කට ආසන්න පිරිසකට", "100% ක සමස්ත වැඩිහිටි ජනතාවට", "දේපළ හා ඉංග්‍රීසි අධ්‍යාපන සුදුසුකම් නිසා 3,000 කට ආසන්න සුළු පිරිසකට පමණක් ඡන්ද බලය ලැබිණි."),
    q("1920 මැනිං ප්‍රතිසංස්කරණය යටතේ ආණ්ඩුකාරවරයාට ලබාදී තිබූ 'ප්‍රමාණික බලය' (Certification Power) යනු කුමක්ද?", "නිල නොලත් බහුතරය ප්‍රතික්ෂේප කළත් වැදගත් පනතක් නීතිගත කිරීමේ බලය", "සර්වජන ඡන්දය පැවැත්වීමේ බලය", "පාසල් විභාග සහතික නිකුත් කිරීමේ බලය", "කැබිනට් ඇමතිවරුන් ඉවත් කිරීමේ බලය", "නිල නොලත් බහුතරය පාලනය කිරීමට ආණ්ඩුකාරවරයාට මෙම විශේෂ බලය හිමිවිය."),
    q("1924 මැනිං-ඩෙවොන්ෂයර් ව්‍යවස්ථාව යටතේ ව්‍යවස්ථාදායක සභාවේ ඡන්දයෙන් තේරී පත්වූ ප්‍රාදේශීය මන්ත්‍රීවරුන් සංඛ්‍යාව කීයද?", "23 දෙනෙකි", "12 දෙනෙකි", "37 දෙනෙකි", "50 දෙනෙකි", "1924 සභාවේ මන්ත්‍රීවරුන් 49 අතරින් ප්‍රාදේශීය ඡන්දයෙන් 23 දෙනෙකු තේරී පත් වූහ."),
    q("1924 ව්‍යවස්ථාව යටතේ 'දෝෂාරෝපණයකින් තොරව පාලනය විවේචනය කිරීම' හැඳින්වූයේ කුමන ආකාරයෙන්ද?", "වගකීමෙන් තොර නියෝජිත බලය ලෙස", "විධායක ජනාධිපති ක්‍රමය ලෙස", "පූර්ණ ස්වයංපාලනය ලෙස", "සමානුපාතික පාලනය ලෙස", "විධායක බලය රජයේ නිලධාරීන් සතුවූ අතර නියෝජිතයන්ට විධායක වගකීමක් නොතිබිණි."),
    q("1931 ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ ඡන්ද බලය හිමිවීමේදී ඡන්දදායකයන්ගෙන් ඉවත් කරන ලද සීමාවන් මොනවාද?", "ආදායම්, දේපළ, ස්ත්‍රී පුරුෂ හා සාක්ෂරතා සීමාවන්", "පුරවැසිභාවය පිළිබඳ නීති", "වයස අවුරුදු 21 සීමාව", "ලියාපදිංචි වීමේ ක්‍රමවේදය", "වයස 21 සම්පූර්ණ වීම හැර සෙසු සීමාවන් ඉවත් කර සර්වජන ඡන්දය ලබාදෙන ලදී."),
    q("ඩොනමෝර් කොමිසමට විධායක කාරක සභා ක්‍රමය යෝජනා කිරීම සඳහා ආදර්ශය වූයේ කුමන ආයතනයේ ක්‍රමයද?", "ලන්ඩන් ප්‍රාන්ත සභා ක්‍රමය", "ඇමරිකානු කොංග්‍රස් මණ්ඩලය", "ඉන්දීය ලෝක් සභාව", "ප්‍රංශ සෙනෙට් සභාව", "ලන්ඩන් නගර සභාවේ (London County Council) කාරක සභා ආකෘතිය මෙයට පාදක විය."),
    q("1931 රාජ්‍ය මන්ත්‍රණ සභාවේ විධායක කාරක සභා හතෙන් 'වැදගත්ම ස්වදේශීය තනතුර' ලෙස සැලකුණේ කුමක්ද?", "සභානායක හා ස්වදේශ කටයුතු කාරක සභා සභාපති", "රාජ්‍ය ලේකම් තනතුර", "මුදල් ලේකම් තනතුර", "ආණ්ඩුකාරවරයාගේ ලේකම්", "ශ්‍රීමත් ඩී.බී. ජයතිලක මහතා ප්‍රථම සභානායක හා ස්වදේශ කටයුතු අමාත්‍යවරයා විය."),
    q("1931 සිට 1947 දක්වා ක්‍රියාත්මක වූ ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ මුළුමනින්ම පැවැත්වූ මහා මැතිවරණ ගණන කීයද?", "2 කි", "5 කි", "1 කි", "4 කි", "1931 සහ 1936 වර්ෂවල රාජ්‍ය මන්ත්‍රණ සභා මැතිවරණ දෙකක් පැවැත්විණි."),
    q("1931 ඩොනමෝර් ක්‍රමය තුළ දේශපාලන නායකයන් වඩාත් ඉල්ලා සිටි මූලික වෙනස්කම කුමක්ද?", "රාජ්‍ය නිලධාරීන් තිදෙනා ඉවත් කර පූර්ණ කැබිනට් වගකීම් පාලනයක් ලබාදීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීම", "ව්‍යවස්ථාදායක සභාවට ආපසු යාම", "ජාතික නියෝජනය නැවත පැනවීම", "බ්‍රිතාන්‍ය නිලධාරීන් සතු ප්‍රධාන විෂයන් 3 ලාංකික ඇමතිවරුන්ට ලබාගැනීමට ඉල්ලා සිටියහ."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ පළමු නියෝජිත මන්ත්‍රී මණ්ඩලයේ කථානායකවරයා වූයේ කවුද?", "සර් ෆ්‍රැන්සිස් මොලමුරේ මහතා", "ටී.බී. සුබසිංහ මහතා", "ඇල්බට් එෆ්. පීරිස් මහතා", "හියු ප්‍රනාන්දු මහතා", "1947 නියෝජිත මන්ත්‍රී මණ්ඩලයේ ප්‍රථම කථානායක ධුරයට සර් ෆ්‍රැන්සිස් මොලමුරේ පත්විය."),
    q("1947 සෝල්බරි ව්‍යවස්ථාවේ 'පත් කළ මන්ත්‍රීවරුන් 6 දෙනා' පත් කිරීමේ අරමුණ කුමක්ද?", "නියෝජනය නොවූ සුළු ජන කොටස් හා විශේෂ අංශ නියෝජනය කිරීම", "විපක්ෂයේ බහුතරය අඩු කිරීම", "සෙනෙට් සභාව විසුරුවා හැරීම", "පළාත් සභා පාලනය කිරීම", "යුරෝපීය, බර්ගර් හා මැලේ වැනි සුළුතර හා වාණිජ අංශ නියෝජනයට පත්කළ මන්ත්‍රීවරුන් යොදාගැනිණි."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව අනුව පළමු පාර්ලිමේන්තු මැතිවරණයේදී ඡන්දදායකයන්ට එක් ඡන්ද කොට්ඨාසයකට වැඩි මන්ත්‍රීවරුන් පත් කිරීමේ විශේෂ ක්‍රමය කුමක්ද?", "බහු මන්ත්‍රී ආසන ක්‍රමය", "සමානුපාතික ලැයිස්තු ක්‍රමය", "මිශ්‍ර ක්‍රමය", "ජනමත විචාරණ ක්‍රමය", "ජනවාර්ගික විවිධත්වය ඇති කොළඹ මධ්‍යම වැනි ප්‍රදේශවල බහු මන්ත්‍රී ආසන ක්‍රියාත්මක විය."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ අධිකරණ නිලධාරීන් පත් කිරීම සඳහා පිහිටුවන ලද ස්වාධීන මණ්ඩලය කුමක්ද?", "අධිකරණ සේවා කොමිෂන් සභාව", "ජාතික පොලිස් කොමිසම", "අල්ලස් කොමිසම", "විගණන සේවා කොමිසම", "අධිකරණයේ ස්වාධීනත්වය රැකීමට සෝල්බරි ව්‍යවස්ථාවෙන් අධිකරණ සේවා කොමිසම පිහිටුවීය."),
    q("සෝල්බරි ව්‍යවස්ථාව යටතේ රාජ්‍ය සේවකයන් බඳවා ගැනීම හා විනය පාලනය පැවරී තිබුණේ කුමන ආයතනයටද?", "රාජ්‍ය සේවා කොමිෂන් සභාවට", "ව්‍යවස්ථා අධිකරණයට", "පළාත් සභාවලට", "සෙනෙට් සභාවට", "රාජ්‍ය සේවයේ මධ්‍යස්ථභාවය රැකීමට රාජ්‍ය සේවා කොමිසම ස්ථාපිත කෙරිණි."),
    q("සෝල්බරි ව්‍යවස්ථාව යටතේ ශ්‍රී ලංකාවේ ප්‍රථම වතාවට කාන්තා අග්‍රාමාත්‍යවරියක් තේරී පත්වූයේ කුමන වර්ෂයේදීද?", "1960", "1952", "1972", "1977", "1960 ජූලි මැතිවරණයෙන් සිරිමාවෝ බණ්ඩාරනායක මැතිණිය අග්‍රාමාත්‍ය ධුරයට පත්වූවාය."),
    q("සෝල්බරි ව්‍යවස්ථාවේ සෙනෙට් සභාව විවේචනයට ලක් වූ ප්‍රධාන හේතුව කුමක්ද?", "පහළ මන්ත්‍රී මණ්ඩලයේ පනත් ප්‍රමාද කිරීම හා මහජන ඡන්දයෙන් පත් නොවීම", "සෙනෙට් සභිකයන් 300 ක් සිටීම", "විදේශිකයන් පමණක් සිටීම", "සෙනෙට් සභාව අයවැය සැකසීම", "තේරී පත්වූ නියෝජිතයන්ගේ තීරණ ප්‍රමාද කිරීම නිසා 1971 දී සෙනෙට් සභාව අහෝසි කෙරිණි."),
    q("1948 සිට 1972 දක්වා ශ්‍රී ලංකාව පොදුරාජ්‍ය මණ්ඩලය තුළ පිළිගැනුණු රාජ්‍ය ප්‍රධානියා කවුද?", "බ්‍රිතාන්‍ය මහරැජින හෝ රජතුමා", "ඉන්දීය ජනාධිපතිවරයා", "ශ්‍රී ලංකාවේ අගවිනිසුරු", "රාජ්‍ය මන්ත්‍රණ සභා සභාපති", "ඩොමීනියන් කාලයේදී බ්‍රිතාන්‍ය කිරීටය රාජ්‍ය නායකයා ලෙස පැවතුණි."),
    q("1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාව සම්පාදනය කිරීමේදී පාර්ලිමේන්තුව තුළින්ම සම්පාදක මණ්ඩලයක් පිහිටුවීමට මුල් වූ ස්ථානය කුමක්ද?", "නවරත්න ශාලාව", "බණ්ඩාරනායක සම්මන්ත්‍රණ ශාලාව", "ශ්‍රේෂ්ඨාධිකරණ සංකීර්ණය", "මහනුවර මඟුල් මඩුව", "කොළඹ රාජකීය විද්‍යාලයේ නවරත්න ශාලාවේ රැස්වී ආණ්ඩුක්‍රම සම්පාදක මණ්ඩලය පිහිටුවන ලදී."),
    q("1972 පළමු ජනරජ ව්‍යවස්ථාව ක්‍රියාත්මක වූයේ කුමන කාල පරිච්ඡේදය තුළද?", "1972 සිට 1978 දක්වා", "1948 සිට 1972 දක්වා", "1931 සිට 1947 දක්වා", "1978 සිට 1987 දක්වා", "1972 මැයි 22 සිට 1978 සැප්තැම්බර් 07 දක්වා ප්‍රථම ජනරජ ව්‍යවස්ථාව ක්‍රියාත්මක විය."),
    q("1972 ජනරජ ව්‍යවස්ථාව යටතේ 'රාජ්‍ය සේවයේ කටයුතු' පැවරී තිබුණේ කාටද?", "කැබිනට් අමාත්‍ය මණ්ඩලයට", "ස්වාධීන රාජ්‍ය සේවා කොමිසමට", "අධිකරණ කොමිසමට", "ව්‍යවස්ථාදායක සභාවට", "1972 දී ස්වාධීන කොමිසම අහෝසි කර රාජ්‍ය සේවය කැබිනට් මණ්ඩලය යටතට පත් කෙරිණි."),
    q("1972 ව්‍යවස්ථාවේ 'ව්‍යවස්ථා අධිකරණය' සතු ප්‍රධාන කාර්යභාරය කුමක් වීද?", "පනත් කෙටුම්පත් ව්‍යවස්ථාවට අනුකූලදැයි තීරණය කිරීම", "මිනීමැරුම් නඩු විභාග කිරීම", "පළාත් පාලන බදු අය කිරීම", "මැතිවරණ දිස්ත්‍රික්ක බෙදීම", "පනතක් සම්මත කිරීමට පෙර එහි ව්‍යවස්ථානුකූලභාවය පරීක්ෂා කිරීම ව්‍යවස්ථා අධිකරණය ඉටු කළේය."),
    q("1972 ව්‍යවස්ථාව යටතේ ශ්‍රී ලංකාව පොදුරාජ්‍ය මණ්ඩලය තුළ දැරූ නව තත්ත්වය කුමක්ද?", "සාමාජික ස්වෛරී ජනරජයක්", "බ්‍රිතාන්‍ය ඩොමීනියන් රාජ්‍යයක්", "යටත්විජිත ප්‍රාන්තයක්", "සංරක්ෂිත රාජ්‍යයක්", "ජනරජයක් වීමෙන් පසුවද ස්වෛරී ජනරජයක් ලෙස ශ්‍රී ලංකාව පොදුරාජ්‍ය මණ්ඩලයේ රැඳී සිටියේය."),
    q("1972 ව්‍යවස්ථාව යටතේ පැවති 'බුද්ධාගමට ප්‍රමුඛස්ථානය' ලබාදීම පිළිබඳ වගන්තිය 1978 ව්‍යවස්ථාවේ කුමන පරිච්ඡේදයට අයත්ද?", "II වන පරිච්ඡේදය", "I වන පරිච්ඡේදය", "III වන පරිච්ඡේදය", "IV වන පරිච්ඡේදය", "1978 ව්‍යවස්ථාවේ II වන පරිච්ඡේදයේ 9 වන වගන්තියෙන් බුද්ධාගමට ප්‍රමුඛස්ථානය ලැබේ."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව කෙටුම්පත් කිරීම සඳහා පත් කරන ලද පාර්ලිමේන්තු තේරීම් කාරක සභාවේ සභාපතිවරයා කවුද?", "ජේ.ආර්. ජයවර්ධන මහතා", "ආර්. ප්‍රේමදාස මහතා", "මෛත්‍රීපාල සේනානායක මහතා", "අප්පාපිල්ලේ අමිර්තලිංගම් මහතා", "එවකට අගමැති ජේ.ආර්. ජයවර්ධන මහතාගේ සභාපතිත්වයෙන් තේරීම් කාරක සභාව ක්‍රියා කළේය."),
    q("1978 ව්‍යවස්ථාවේ විධායක ජනාධිපති ක්‍රමය සකස් කිරීමේදී ප්‍රධාන වශයෙන් ආභාසය ලැබූ විදේශීය ව්‍යවස්ථා දෙක මොනවාද?", "ප්‍රංශ සහ ඇමරිකානු ව්‍යවස්ථා", "රුසියානු සහ චීන ව්‍යවස්ථා", "සෞදි සහ ඉරාන ව්‍යවස්ථා", "ජපන් සහ තායිලන්ත ව්‍යවස්ථා", "ඇමරිකානු ජනාධිපති බලතල හා ප්‍රංශ අර්ධ-ජනාධිපති ආකෘතිය ආභාසයට ගැනිණි."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ ප්‍රථම වරට පිහිටුවන ලද නව අධිකරණ ආයතනය කුමක්ද?", "අභියාචනාධිකරණය", "මහේස්ත්‍රාත් අධිකරණය", "දිසා අධිකරණය", "ව්‍යවස්ථා අධිකරණය", "ප්‍රිවි කවුන්සිලය අහෝසි වීමෙන් පසු 1978 දී ශ්‍රේෂ්ඨාධිකරණයට පහළින් අභියාචනාධිකරණය පිහිටුවීය."),
    q("1978 ව්‍යවස්ථාව මඟින් පුරවැසි පැමිණිලි විභාග කිරීමට හඳුන්වා දුන් 'පරිපාලන කටයුතු පිළිබඳ පාර්ලිමේන්තු කොමසාරිස්' කවුද?", "ඔම්බුඩ්ස්මන්වරයා", "විගණකාධිපතිවරයා", "මැතිවරණ කොමසාරිස්වරයා", "නීතිපතිවරයා", "1978 ව්‍යවස්ථාවේ 156 වන වගන්තියෙන් ඔම්බුඩ්ස්මන් ධුරය ස්ථාපිත කෙරිණි."),
    q("1978 ව්‍යවස්ථාව යටතේ 2 වන සංශෝධනය සිදු කරන ලද්දේ කුමන අරමුණකින්ද?", "ජනාධිපතිවරණයට පෙර 1977 පත්වූ ජනාධිපතිවරයාගේ ධුර කාලය නියම කිරීම", "පක්ෂ මාරු කිරීමට ඉඩ දීම සඳහා", "පළාත් සභා ආණ්ඩුකාරවරුන් පත් කිරීමට", "මැතිවරණ කොමිසම අහෝසි කිරීමට", "1979 සම්මත 2 වන සංශෝධනයෙන් පක්ෂයෙන් ඉවත්වන මන්ත්‍රී ධුර පිළිබඳ විධිවිධාන ඇතුළු සංශෝධන කෙරිණි."),
    q("ජනාධිපතිවරයෙකුට සිය පළමු ධුර කාලයෙන් වසර 4ක් සපිරුණු පසු නැවත ජනාධිපතිවරණයක් කැඳවීමට ඉඩ දුන් සංශෝධනය කුමක්ද?", "3 වන සංශෝධනය", "13 වන සංශෝධනය", "17 වන සංශෝධනය", "21 වන සංශෝධනය", "1982 සම්මත කළ 3 වන සංශෝධනයෙන් 1982 ජනාධිපතිවරණය පැවැත්වීමට ඉඩ සැලසිණි."),
    q("ශ්‍රී ලංකාවේ පළමු වරට ජනාධිපතිවරණයක් පවත්වන ලද්දේ කුමන වර්ෂයේදීද?", "1982", "1978", "1988", "1994", "1982 ඔක්තෝබර් 20 දින ප්‍රථම ජනාධිපතිවරණය පැවැත්වී ජේ.ආර්. ජයවර්ධන මහතා තේරී පත්විය."),
    q("1978 ව්‍යවස්ථාවේ 6 වන සංශෝධනය මඟින් තහනම් කරන ලද්දේ කුමක්ද?", "රට බෙදා වෙන් කිරීම හෝ ඒකීයභාවයට එරෙහි වීම", "සර්වජන ඡන්ද බලය භාවිත කිරීම", "මූලික අයිතිවාසිකම් නඩු පැවරීම", "ද්විත්ව පුරවැසිභාවය ලබාදීම", "1983 සම්මත කළ 6 වන සංශෝධනයෙන් වෙනම රාජ්‍යයක් වෙනුවෙන් පෙනී සිටීම තහනම් කෙරිණි."),
    q("1978 ව්‍යවස්ථාවේ 7 වන සංශෝධනය මඟින් ඇති කළ පරිපාලන ඒකක වන්නේ කුමක්ද?", "කිලිනොච්චි පරිපාලන දිස්ත්‍රික්කය පිහිටුවීම හා කොමසාරිස් පත්වීම්", "පළාත් සභා 9 පිහිටුවීම", "ජාතික ලැයිස්තු මන්ත්‍රී ධුර ඇති කිරීම", "සෙනෙට් සභාව නැවත පිහිටුවීම", "1983 7 වන සංශෝධනයෙන් උතුරු පළාතේ කිලිනොච්චි පරිපාලන දිස්ත්‍රික්කය ස්ථාපිත විය."),
    q("1978 ව්‍යවස්ථාවේ 10 වන සංශෝධනය මඟින් සිදු කළ වෙනස කුමක්ද?", "හදිසි නීති කාලය දීර්ඝ කිරීමට පාර්ලිමේන්තුවේ සරල බහුතරය ප්‍රමාණවත් කිරීම", "ජනාධිපතිවරණය අවලංගු කිරීම", "මැතිවරණ කොමිසම පිහිටුවීම", "අභියාචනාධිකරණය අහෝසි කිරීම", "1986 10 වන සංශෝධනයෙන් හදිසි නීති දීර්ඝ කිරීම පිළිබඳ 155(8) වගන්තිය සංශෝධනය කෙරිණි."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ මන්ත්‍රී සංඛ්‍යාව 196 සිට 225 දක්වා ඉහළ දමන ලද වර්ෂය කුමක්ද?", "1988", "1978", "1994", "2001", "1988 මැයි මාසයේ සම්මත කළ 14 වන සංශෝධනයෙන් මන්ත්‍රී සංඛ්‍යාව 225 ක් විය."),
    q("1988 සම්මත කළ 14 වන සංශෝධනය මඟින් ජනාධිපතිවරයාගේ පුරවැසි මුක්තිය පිළිබඳව එකතු කළ වගන්තිය හෝ වෙනස කුමක්ද?", "මැතිවරණ පෙත්සම් හා දිස්ත්‍රික් ආසන ගණනය විධිමත් කිරීම", "පළාත් සභා මුළුමනින්ම අහෝසි කිරීම", "රාජ්‍ය භාෂා ඉංග්‍රීසි පමණක් කිරීම", "අග්‍රාමාත්‍ය ධුරය අහෝසි කිරීම", "14 වන සංශෝධනයෙන් මන්ත්‍රී සංඛ්‍යාව 225 කිරීම හා ජාතික ලැයිස්තුව හඳුන්වා දීම සිදුවිය."),
    q("2001 වර්ෂයේ 17 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය පාර්ලිමේන්තුවේදී සම්මත වූයේ කවර ආකාරයෙන්ද?", "පක්ෂ විපක්ෂ සියලු දෙනාගේ පොදු එකඟතාවයෙන්", "ජනමත විචාරණයකින් පසුව", "හදිසි නීති ආඥාවකින්", "ශ්‍රේෂ්ඨාධිකරණ නියෝගයකින්", "17 වන සංශෝධනය යහපාලනය උදෙසා පාර්ලිමේන්තුවේ පුළුල් බහුපාර්ශ්වික එකඟතාවෙන් සම්මත විය."),
    q("17 වන සංශෝධනය යටතේ පිහිටුවන ලද ප්‍රධාන ස්වාධීන කොමිෂන් සභා අතරට අයත් නොවන්නේ කුමක්ද?", "විදේශ වෙළඳ කොමිෂන් සභාව", "මැතිවරණ කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "ජාතික පොලිස් කොමිෂන් සභාව", "17 වන සංශෝධනයෙන් මැතිවරණ, රාජ්‍ය සේවා, පොලිස්, මානව හිමිකම් හා අල්ලස් කොමිෂන් ශක්තිමත් කෙරිණි."),
    q("18 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය මඟින් ව්‍යවස්ථාදායක සභාව වෙනුවට හඳුන්වා දුන් සභාව කුමක්ද?", "පාර්ලිමේන්තු සභාව", "සෙනෙට් සභාව", "විධායක කාරක සභාව", "ජාතික රාජ්‍ය සභාව", "18 වන සංශෝධනයෙන් 5 දෙනෙකුගෙන් යුත් පාර්ලිමේන්තු සභාවක් පිහිටුවා ජනාධිපතිට නිරීක්ෂණ ලබාදීම සිදුවිය."),
    q("19 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය මඟින් පාර්ලිමේන්තු මැතිවරණයකින් පසු ජාතික ආණ්ඩුවක් පිහිටුවීමට අදාළව සිදුකළ වෙනස කුමක්ද?", "කැබිනට් අමාත්‍ය සංඛ්‍යාව 30 කට සීමා කර ජාතික ආණ්ඩුවකදී වැඩි කිරීමට ඉඩ දීම", "කැබිනට් මණ්ඩලය සම්පූර්ණයෙන් අහෝසි කිරීම", "මන්ත්‍රී සංඛ්‍යාව 500 දක්වා වැඩි කිරීම", "සෙනෙට් සභාව පිහිටුවීම", "19 වන සංශෝධනයෙන් සාමාන්‍ය කැබිනට් ඇමති ධුර 30 ට සීමා කරන ලදී."),
    q("19 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය යටතේ පුරවැසියෙකුට ජනාධිපතිවරණයට ඉදිරිපත් වීමට තිබිය යුතු අවම වයස කුමක් වීද?", "අවුරුදු 35", "අවුරුදු 18", "අවුරුදු 25", "අවුරුදු 40", "19 වන සංශෝධනයෙන් අවම වයස 35ක් කළ අතර 20 වන සංශෝධනයෙන් යළි 30 කෙරිණි."),
    q("2022 21 වන ව්‍යවස්ථා සංශෝධනය මඟින් විගණකාධිපති සහ මහ බැංකු අධිපති පත් කිරීමට අදාළව ගත් පියවර කුමක්ද?", "ව්‍යවස්ථාදායක සභාවේ අනුමැතියට යටත් කිරීම", "පෞද්ගලික බැංකුවලට පැවරීම", "පළාත් සභාවලට පැවරීම", "විදේශ ආයතනවලට පැවරීම", "21 වන සංශෝධනයෙන් මහ බැංකු අධිපති හා විගණකාධිපති පත්වීම් ව්‍යවස්ථාදායක සභාවේ අනුමැතියට යටත් කළේය."),
    q("1978 ව්‍යවස්ථාවේ 'අනන්‍ය වූ ව්‍යවස්ථානුකූලභාවය' රැකගැනීම සඳහා පනත් කෙටුම්පතක් සම්බන්ධයෙන් පෙත්සමක් ගොනු කළ හැකි කාලය කීයද?", "පාර්ලිමේන්තු න්‍යාය පත්‍රයට ඇතුළත් කළ දින සිට දින 14 ක් ඇතුළත", "පනත සම්මත වී වසර 2 කට පසුව", "මීළඟ මැතිවරණයෙන් පසුව", "පැය 24 ක් ඇතුළත පමණක්", "121 වන වගන්තිය අනුව දින 14 ක් තුළ ශ්‍රේෂ්ඨාධිකරණයට පෙත්සම් ඉදිරිපත් කළ හැක."),
    q("'ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනයක්' යන්නෙන් අදහස් කෙරෙන නිවැරදි ක්‍රියාවලිය කුමක්ද?", "ව්‍යවස්ථාවේ නියමිත ක්‍රියාපටිපාටිය අනුව වගන්ති වෙනස් කිරීම හෝ අලුතින් එක් කිරීම", "අමාත්‍ය මණ්ඩලය රහසිගතව ව්‍යවස්ථාව ඉරා දැමීම", "නගර සභාවක් විසින් නව නීති පැනවීම", "පොලිස්පතිවරයා චක්‍රලේඛයක් නිකුත් කිරීම", "1978 ව්‍යවස්ථාවේ 82 හා 83 වගන්ති අනුව විධිමත්ව පාර්ලිමේන්තුවේ 2/3 කින් සංශෝධන කෙරේ."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම වරට ලාංකිකයන්ට 'ඇමති මණ්ඩලයක වගකීම් දරමින්' පාලනයට හුරු වීමට අවස්ථාව ලැබුණේ කුමන ව්‍යවස්ථාව යටතේද?", "1931 ඩොනමෝර් ආණ්ඩුක්‍රමය", "1833 කෝල්බෲක් ආණ්ඩුක්‍රමය", "1910 කෲව්-මැකලම් ආණ්ඩුක්‍රමය", "1920 මැනිං ආණ්ඩුක්‍රමය", "ඩොනමෝර් විධායක කාරක සභා ක්‍රමයෙන් සෞඛ්‍ය, අධ්‍යාපන, කෘෂිකර්ම වැනි අමාත්‍ය වගකීම් ලාංකිකයන්ට ලැබිණි."),
    q("1947 සෝල්බරි ව්‍යවස්ථාවේ ප්‍රධාන ලක්ෂණයක් වූ 'පාර්ලිමේන්තු උත්තරීතරභාවය' සීමා වූයේ කුමන වගන්තියෙන්ද?", "29(2) වගන්තියෙන්", "1 වන වගන්තියෙන්", "148 වන වගන්තියෙන්", "126 වන වගන්තියෙන්", "සුළුතර අයිතීන් ආරක්ෂා කළ 29(2) වගන්තියට පටහැනිව නීති සෑදීමට පාර්ලිමේන්තුවට බලයක් නොතිබිණි."),
    q("1972 ව්‍යවස්ථාවේ 'ජාතික රාජ්‍ය සභාව' සෝල්බරි පාර්ලිමේන්තුවෙන් වෙනස් වූ ප්‍රධාන කරුණක් කුමක්ද?", "සෙනෙට් සභාවක් නොමැති ඒකමණ්ඩල ව්‍යවස්ථාදායකයක් වීම", "විධායක ජනාධිපතිවරයෙකු සභාපති වීම", "මන්ත්‍රීවරුන් සමානුපාතික ක්‍රමයෙන් පත් වීම", "විදේශ නියෝජිතයන් 20ක් සිටීම", "1972 දී සෙනෙට් සභාව අහෝසි කර තනි මණ්ඩලයක් පිහිටුවීම ප්‍රධාන වෙනසක් විය."),
    q("1978 ව්‍යවස්ථාවේ VI වන පරිච්ඡේදයෙන් විස්තර කෙරෙන්නේ කුමන ආයතනය හෝ මාතෘකාව පිළිබඳවද?", "රාජ්‍ය ප්‍රතිපත්ති මෙහෙයවීමේ මූලධර්ම හා මූලික යුතුකම්", "මූලික අයිතිවාසිකම්", "විධායක ජනාධිපති ධුරය", "පළාත් සභා ක්‍රමය", "27 හා 28 වගන්ති ඇතුළත් VI වන පරිච්ඡේදයේ රාජ්‍ය ප්‍රතිපත්ති මූලධර්ම හා පුරවැසි යුතුකම් දැක්වේ."),
    q("1978 ව්‍යවස්ථාවේ IV වන පරිච්ඡේදය මඟින් නියම කර ඇත්තේ කුමන පාලන අංශයද?", "රාජ්‍ය භාෂාව", "අධිකරණය", "මූල්‍ය පාලනය", "මැතිවරණ කොමිසම", "IV වන පරිච්ඡේදයේ 18–25 වගන්ති මඟින් රාජ්‍ය භාෂා හා ජාතික භාෂා විධිවිධාන දක්වයි."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'හදිසි පනත් කෙටුම්පත්' (Urgent Bills) ඉදිරිපත් කිරීමේ බලය සීමා කරන ලද්දේ කුමන සංශෝධනයෙන්ද?", "19 වන සංශෝධනය", "13 වන සංශෝධනය", "15 වන සංශෝධනය", "16 වන සංශෝධනය", "19 වන සංශෝධනයෙන් ජාතික ආරක්ෂාව හා ආපදා හැර හදිසි පනත් ඉදිරිපත් කිරීම සීමා කළේය."),
    q("1931 ඩොනමෝර් ආණ්ඩුක්‍රමය හා 1947 සෝල්බරි ආණ්ඩුක්‍රමය අතර පවතින ප්‍රධාන වෙනස්කම කුමක්ද?", "සෝල්බරි ක්‍රමයේ කැබිනට් හා පක්ෂ ක්‍රමය පැවති නමුත් ඩොනමෝර් ක්‍රමයේ කාරක සභා පැවතීම", "ඩොනමෝර් ක්‍රමයේ විධායක ජනාධිපති සිටි නමුත් සෝල්බරි ක්‍රමයේ නොසිටීම", "සෝල්බරි ක්‍රමයේ සර්වජන ඡන්දය අහෝසි කිරීම", "ඩොනමෝර් ක්‍රමයේ සෙනෙට් සභාවක් තිබීම", "ඩොනමෝර් කාරක සභා වෙනුවට සෝල්බරි ක්‍රමයේ අගමැති ප්‍රමුඛ කැබිනට් මණ්ඩලය හඳුන්වා දුනි."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ අග්‍රාණ්ඩුකාරවරයාගේ තීරණ ගැනීමේ ස්වභාවය කෙබඳු වීද?", "අග්‍රාමාත්‍යවරයාගේ උපදෙස් මත ක්‍රියා කළ නාමික නායකයෙකු වීම", "හිතුමතේ පාර්ලිමේන්තු නීති ප්‍රතික්ෂේප කිරීම", "හමුදා නීතිය පමණක් ක්‍රියාත්මක කිරීම", "මන්ත්‍රීවරුන් 101 දෙනාම පත් කිරීම", "බ්‍රිතාන්‍ය මහරැජිනගේ නියෝජිතයා ලෙස අග්‍රාණ්ඩුකාරවරයා සාම්ප්‍රදායිකව අගමැති උපදෙස් මත ක්‍රියා කළේය."),
    q("1972 ව්‍යවස්ථාවට 'ජනරජ ව්‍යවස්ථාව' යනුවෙන් හැඳින්වීමට ප්‍රධානම හේතුව කුමක්ද?", "බ්‍රිතාන්‍ය රැජින රාජ්‍ය නායකත්වයෙන් ඉවත් කර ශ්‍රී ලංකාව ස්වාධීන ජනරජයක් බවට පත්වීම", "විධායක ජනාධිපති ක්‍රමය ඇති කිරීම", "සමානුපාතික මැතිවරණ ක්‍රමය හඳුන්වා දීම", "මැතිවරණ දිස්ත්‍රික්ක 22 බෙදීම", "1972 දී බ්‍රිතාන්‍ය කිරීටය සමඟ තිබූ ව්‍යවස්ථාපිත සම්බන්ධය සම්පූර්ණයෙන් අවසන් කෙරිණි."),
    q("1978 ව්‍යවස්ථාවේ 'ජනාධිපති ධුර කාලය වාර දෙකකට සීමා කිරීම' නැවත පනවන ලද සංශෝධනය කුමක්ද?", "19 වන සංශෝධනය", "18 වන සංශෝධනය", "14 වන සංශෝධනය", "15 වන සංශෝධනය", "18 වන සංශෝධනයෙන් ඉවත් කළ වාර දෙකේ සීමාව 19 වන සංශෝධනයෙන් යළි පනවන ලදී."),
    q("1987 පළාත් සභා පිහිටුවීමත් සමඟම 13 වන සංශෝධනයෙන් ඇති කළ ප්‍රධාන පළාත් තනතුරු දෙක කවරේද?", "පළාත් ආණ්ඩුකාරවරයා සහ ප්‍රධාන අමාත්‍යවරයා", "විධායක ජනාධිපති සහ කථානායක", "සෙනෙට් සභාපති සහ විගණකාධිපති", "දිසා විනිසුරු සහ නීතිපති", "ජනාධිපති පත්කරන ආණ්ඩුකාරවරයා හා ඡන්දයෙන් පත්වන මහ ඇමති පළාත් සභාවේ ප්‍රධාන තනතුරු වේ."),
    q("1833 කෝල්බෲක් ප්‍රතිසංස්කරණ යටතේ ආණ්ඩුවේ පරිපාලන කටයුතු කාර්යක්ෂම කිරීමට නිර්දේශ කළ තවත් වැදගත් යෝජනාවක් කුමක්ද?", "සිවිල් සේවය ප්‍රතිසංවිධානය කිරීම හා ඉංග්‍රීසි අධ්‍යාපනය ව්‍යාප්ත කිරීම", "සිංහල භාෂාව පමණක් රාජ්‍ය භාෂාව කිරීම", "පළාත් සභා පිහිටුවීම", "විශ්වවිද්‍යාල 10ක් ආරම්භ කිරීම", "රාජ්‍ය වෙළඳ ඒකාධිකාරය අවසන් කර සිවිල් සේවය හා අධ්‍යාපනය ප්‍රතිසංස්කරණය කිරීම කෝල්බෲක් නිර්දේශ විය."),
    q("1920 මැනිං ප්‍රතිසංස්කරණයට පසුව 1924 දී මැනිං-ඩෙවොන්ෂයර් ප්‍රතිසංස්කරණය ගෙන ඒමට ප්‍රධාන හේතුව කුමක්ද?", "1920 ප්‍රතිසංස්කරණයෙන් ලාංකික නියෝජිතයන් සෑහීමකට පත් නොවීම", "1931 ඩොනමෝර් ව්‍යවස්ථාව අසාර්ථක වීම", "ජනරජ ව්‍යවස්ථාව අහෝසි කිරීමට සිදුවීම", "ලෝක යුද්ධය 1924 දී අවසන් වීම", "1920 ක්‍රමයේ පැවති සීමාවන් නිසා ජාතික සංගමය වැඩි බලතල ඉල්ලා උද්ඝෝෂණය කළේය."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ පැවති පළමු මහ මැතිවරණයෙන් පසු ඒකාබද්ධ වී ආණ්ඩුව පිහිටුවූ ප්‍රධාන නායකයා කවුද?", "ඩී.එස්. සේනානායක මහතා", "එස්.ඩබ්ලිව්.ආර්.ඩී. බණ්ඩාරනායක මහතා", "පීටර් කෙනමන් මහතා", "ජේ.ආර්. ජයවර්ධන මහතා", "1947 එක්සත් ජාතික පක්ෂයේ නායක ඩී.එස්. සේනානායක මහතා සෙසු මන්ත්‍රීන් සමඟ ආණ්ඩුව පිහිටුවීය."),
    q("1959 වර්ෂයේදී ඡන්දදායකයන් සඳහා වයස අවුරුදු 21 සිට 18 දක්වා අඩු කිරීමේදී පැවතියේ කුමන ආණ්ඩුක්‍රම ව්‍යවස්ථාවද?", "1947 සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "1931 ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "1972 පළමු ජනරජ ව්‍යවස්ථාව", "1978 දෙවන ජනරජ ව්‍යවස්ථාව", "1959 අංක 11 දරන ලංකා මැතිවරණ සංශෝධන පනතින් වයස 18 දක්වා අඩු කෙරිණි."),
    q("1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ අවසන් අධිකරණ බලය හිමිවූ ඉහළම අධිකරණය කුමක්ද?", "ශ්‍රී ලංකා ශ්‍රේෂ්ඨාධිකරණය", "ලන්ඩන් ප්‍රිවි කවුන්සිලය", "රාජ්‍ය මන්ත්‍රණ සභාව", "කොළඹ මහේස්ත්‍රාත් අධිකරණය", "1972 ව්‍යවස්ථාවෙන් ප්‍රිවි කවුන්සිලයට අභියාචනා ඉදිරිපත් කිරීම අහෝසි කර මෙරට ශ්‍රේෂ්ඨාධිකරණය ඉහළම අධිකරණය විය."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ XVI වන පරිච්ඡේදයෙන් ප්‍රධාන වශයෙන් ආවරණය වන්නේ කුමක්ද?", "අධිකරණය හා අධිකරණ බලතල", "රාජ්‍ය භාෂා ප්‍රතිපත්තිය", "ජාතික ගීය හා ධජය", "පළාත් පාලන ආදායම් බදු", "1978 ව්‍යවස්ථාවේ XV හා XVI පරිච්ඡේද අධිකරණ ව්‍යුහය හා උපරිමාධිකරණ පිළිබඳ දක්වයි."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව මඟින් 'ජනාධිපතිවරයා පාර්ලිමේන්තුවට වගකිව යුතු බව' දැක්වෙන්නේ කුමන වගන්තියෙන්ද?", "42 වන වගන්තිය", "3 වන වගන්තිය", "9 වන වගන්තිය", "18 වන වගන්තිය", "42 වන වගන්තිය අනුව ජනාධිපතිවරයා සිය බලතල ක්‍රියාත්මක කිරීමේදී පාර්ලිමේන්තුවට වගකිව යුතුය."),
    q("1978 ව්‍යවස්ථාව යටතේ 'රාජ්‍ය සේවා කොමිෂන් සභාව' නැවත ස්වාධීන කිරීමෙන් රාජ්‍ය සේවකයන්ට ලැබුණු ප්‍රධාන වාසිය කුමක්ද?", "දේශපාලන පළිගැනීම්වලින් තොරව කුසලතාව මත උසස්වීම් හා මාරුවීම් ලැබීම", "වැටුප් බදු සම්පූර්ණයෙන් අහෝසි වීම", "විශ්‍රාම යාමේ වයස අවුරුදු 80 වීම", "සෑම රාජ්‍ය සේවකයෙකුටම පාර්ලිමේන්තු මන්ත්‍රී ධුරයක් ලැබීම", "17 හා 21 සංශෝධනවලින් ස්වාධීන PSC ක්‍රමය යළි තහවුරු කෙරිණි."),
    q("2022 දී සම්මත කළ 21 වන සංශෝධනයේ තවත් නාමයක් ලෙස භාවිත වන්නේ කුමක්ද?", "22 වන කෙටුම්පත ලෙස ඉදිරිපත් වී 21 වන සංශෝධනය ලෙස සම්මත වූ පනත", "17 වන අතුරු පනත", "1931 ඩොනමෝර් අතිරේක පනත", "1972 ජනරජ ආඥාව", "2022 දී 22 වන ව්‍යවස්ථා සංශෝධන කෙටුම්පත ලෙස ගැසට් කර 21 වන සංශෝධනය ලෙස සම්මත විය."),
    q("ශ්‍රී ලංකාවේ ව්‍යවස්ථා පරිණාමය තුළ 'සමානුපාතික නියෝජනය' හඳුන්වා දීමෙන් ප්‍රධාන වශයෙන් වාසි සැලසුණේ කුමන පාර්ශ්වයකටද?", "කුඩා දේශපාලන පක්ෂ හා සුළුතර ජන කොටස්වලට", "කේවල ආසන පමණක් දිනන විශාල පක්ෂවලට පමණක්", "නිලලත් බ්‍රිතාන්‍ය නිලධාරීන්ට", "රාජකාරි ක්‍රමයේ ප්‍රධානීන්ට", "ලැබූ ඡන්ද ප්‍රතිශතයට අනුව ආසන බෙදී යන බැවින් කුඩා පක්ෂවලටද පාර්ලිමේන්තු නියෝජනය ලැබිණි."),
    q("1833 කෝල්බෲක් ප්‍රතිසංස්කරණ යටතේ පිහිටුවන ලද විධායක සභාවේ සභාපතිවරයා ලෙස ක්‍රියා කළේ කවුද?", "බ්‍රිතාන්‍ය ආණ්ඩුකාරවරයා", "උගත් ලාංකික නියෝජිතයා", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරු", "මහනුවර අධිකාරම්වරයා", "ආණ්ඩුකාරවරයා ව්‍යවස්ථාදායක හා විධායක සභා දෙකෙහිම ප්‍රධානියා විය."),
    q("1924 ව්‍යවස්ථාදායක සභාවේ පළමු නිලලත් නොවන මන්ත්‍රී බහුතරය හේතුවෙන් ආණ්ඩුකාරවරයා සමඟ නිතර ගැටුම් ඇති වීම නිසා පත්කළ කොමිසම කුමක්ද?", "ඩොනමෝර් කොමිසම", "සෝල්බරි කොමිසම", "කෝල්බෲක් කොමිසම", "මැකලම් කොමිසම", "1924 ව්‍යවස්ථාවේ අඩුපාඩු විමර්ශනයට 1927 දී ඩොනමෝර් කොමිසම පත් කෙරිණි."),
    q("1931 ඩොනමෝර් ව්‍යවස්ථාව යටතේ ආරම්භ කරන ලද කාරක සභා 7 කට අයත් නොවූ විෂයය කුමක්ද?", "විදේශ කටයුතු හා ආරක්ෂාව", "සෞඛ්‍යය", "අධ්‍යාපනය", "කෘෂිකර්මය හා ඉඩම්", "ආරක්ෂාව හා විදේශ කටයුතු බ්‍රිතාන්‍ය රාජ්‍ය ලේකම්වරයා යටතේ තබා ගැනිණි."),
    q("1947 සෝල්බරි ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'විශේෂ බහුතරයකින්' සංශෝධනය කළ යුතු වගන්ති සඳහා අවශ්‍ය වූ පාර්ලිමේන්තු ඡන්ද ප්‍රමාණය කුමක්ද?", "නියෝජිත මන්ත්‍රී මණ්ඩලයේ 2/3 ක බහුතරය", "සරල බහුතරය පමණි", "සෙනෙට් සභාවේ 1/3 ක බහුතරය", "ජනමත විචාරණය පමණි", "සෝල්බරි ව්‍යවස්ථාවේ 29(4) වගන්තිය අනුව ව්‍යවස්ථා සංශෝධනයට 2/3 ක අනුමැතිය අවශ්‍ය විය."),
    q("1972 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'ව්‍යවස්ථාදායක බලය' පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?", "ජාතික රාජ්‍ය සභාවට විදේශීය හෝ අධිකරණ බාධාවකින් තොරව උත්තරීතර නීති සෑදීමේ බලය තිබීම", "බ්‍රිතාන්‍ය පාර්ලිමේන්තුව අනුමත කළ නීති පමණක් බලපැවැත්වීම", "පළාත් සභා නීතිවලට ප්‍රමුඛත්වය ලැබීම", "විධායක ජනාධිපතිගේ නිෂේධ බලයට යටත් වීම", "1972 ව්‍යවස්ථාවේ ජාතික රාජ්‍ය සභාව පරමාධිපත්‍යයේ උත්තරීතර උපකරණය ලෙස ක්‍රියා කළේය."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවෙන් පිහිටුවන ලද ශ්‍රී ලංකා පාර්ලිමේන්තුව ප්‍රථම වරට වර්තමාන ගොඩනැගිල්ල පිහිටි ශ්‍රී ජයවර්ධනපුර කෝට්ටේට ගෙන යන ලද්දේ කවදාද?", "1982", "1972", "1948", "1994", "1982 අප්‍රේල් 29 දින කොළඹ ගාලුමුවදොර පැරණි පාර්ලිමේන්තුවේ සිට ශ්‍රී ජයවර්ධනපුර කෝට්ටේට ගෙන යන ලදී."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 13 වන සංශෝධනයේ 'සමගාමී ලැයිස්තුව' (Concurrent List) යනු කුමක්ද?", "මධ්‍යම රජය හා පළාත් සභා දෙකටම නීති සෑදිය හැකි විෂය ලැයිස්තුව", "විදේශ රටවලට පවරන ලද විෂය ලැයිස්තුව", "පළාත් පාලන බදු ලැයිස්තුව පමණි", "අධිකරණ විනිසුරු නාමලේඛනය", "13 වන සංශෝධනයේ IX වන උපලේඛනයේ පළාත් සභා, සංවෘත හා සමගාමී යන ලැයිස්තු 3ක් ඇත."),
    q("2001 දී 17 වන සංශෝධනයෙන් පසු 2010 දී 18 වන සංශෝධනය ගෙන ඒම නිසා ස්වාධීන කොමිෂන් සභාවලට සිදුවූ ප්‍රධාන වෙනස කුමක්ද?", "ව්‍යවස්ථාදායක සභාව අහෝසි වී ජනාධිපති බලතල වැඩි වීම", "පළාත් සභා බලතල දෙගුණ වීම", "මූලික අයිතිවාසිකම් ශ්‍රේෂ්ඨාධිකරණයෙන් ඉවත් කිරීම", "ඡන්ද වයස අවුරුදු 21 කිරීම", "18 වන සංශෝධනයෙන් ස්වාධීන පත්වීම් ක්‍රමය වෙනුවට ජනාධිපතිට අභිමතය පරිදි පත්කිරීම් හිමිවිය."),
    q("2015 19 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනයේදී ජනාධිපතිවරයාට පෞද්ගලිකව නොපැවරිය හැකිව තිබූ නිල මුක්තියේ සිදුකළ වැදගත් වෙනස කුමක්ද?", "ජනාධිපතිවරයාගේ නිල ක්‍රියාවලට එරෙහිව නීතිපතිට විරුද්ධව මූලික අයිතිවාසිකම් නඩු පැවරීමට ඉඩ දීම", "ජනාධිපතිවරයාට රාජ්‍ය සේවකයන් මාරු කිරීමට ඉඩ දීම", "හදිසි නීති පැනවීම අනිවාර්ය කිරීම", "ව්‍යවස්ථාදායක සභාව අහෝසි කිරීම", "35 වන වගන්තිය සංශෝධනය කර මූලික අයිතිවාසිකම් නඩු පැවරීමට ඇති ඉඩකඩ තහවුරු කෙරිණි."),
    q("ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ව්‍යවස්ථාවක 'උත්තරීතරභාවය' (Supremacy of the Constitution) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "රටේ සෑම නීතියක්ම හා රාජ්‍ය ආයතනයක්ම ව්‍යවස්ථාවට යටත් විය යුතු බව", "අමාත්‍ය මණ්ඩලය ව්‍යවස්ථාවට ඉහළින් සිටින බව", "පොලිස් නියෝග ව්‍යවස්ථාවට වඩා බලවත් බව", "විදේශ ගිවිසුම් ව්‍යවස්ථාව අවලංගු කරන බව", "ව්‍යවස්ථාව රටේ මූලික නීතිය වන අතර අන් කිසිදු නීතියක් ඊට පටහැනි විය නොහැක."),
    q("1833 සිට 1931 දක්වා ලංකාවේ ව්‍යවස්ථා ප්‍රතිසංස්කරණ සඳහා පොදුවේ බලපෑ ප්‍රධාන දේශීය සාධකය කුමක්ද?", "උගත් ලාංකික මධ්‍යම පන්තියේ හා ජාතික ව්‍යාපාරවල නිරන්තර ඉල්ලීම්", "අසල්වැසි රටවල යුද ආක්‍රමණ", "වැවිලි ආර්ථිකය සම්පූර්ණයෙන් බිඳවැටීම", "රාජකාරි ක්‍රමය නැවත ස්ථාපිත කිරීමේ ඉල්ලීම්", "ලාංකිකයන්ට පාලන බලය ලබාගැනීමට ගෙන ගිය සාමකාමී ව්‍යවස්ථාමය සටන් මීට මුල් විය."),
    q("1931 ඩොනමෝර් ආණ්ඩුක්‍රමය යටතේ 'සර්වජන ඡන්ද බලය' හඳුන්වා දීමෙන් පසු මෙරට ඇතිවූ වැදගත් සමාජ සංවර්ධනයක් කුමක්ද?", "නිදහස් අධ්‍යාපනය, සෞඛ්‍ය සේවා හා කම්කරු සුබසාධන නීති සම්මත වීම", "රාජකාරි ක්‍රමය නැවත පැනවීම", "පාසල් සියල්ල වසා දැමීම", "සාමාන්‍ය ජනතාවගේ ඡන්ද අයිතිය අහිමි කිරීම", "මහජන ඡන්දයෙන් පත්වූ මන්ත්‍රීවරුන් පොදු ජන සුබසාධනය කෙරෙහි වැඩි අවධානයක් යොමු කළහ."),
    q("1947 සෝල්බරි ව්‍යවස්ථාව යටතේ 1948 සිට 1972 දක්වා කාලය තුළ රාජ්‍යයේ මුදල් නෝට්ටු හා කාසිවල සඳහන් වූයේ කුමන නාමයද?", "ලංකාව (Ceylon)", "ශ්‍රී ලංකා ජනරජය", "ලංකා ෆෙඩරල් රාජ්‍යය", "තැප්‍රොබේන්", "1972 ජනරජ ව්‍යවස්ථාව තෙක් රාජ්‍යයේ නිල නාමය Ceylon ලෙස පැවතුණි."),
    q("1978 ව්‍යවස්ථාවේ 'විධායක ජනාධිපති ක්‍රමය' හඳුන්වා දීම සඳහා ප්‍රධාන වශයෙන් ඉදිරිපත් කරන ලද තර්කය කුමක්ද?", "ආර්ථික සංවර්ධනය සඳහා ස්ථාවර හා ශක්තිමත් විධායකයක් අවශ්‍ය වීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීමේ අවශ්‍යතාව", "පළාත් සභා ක්‍රමය නැවැත්වීමේ අවශ්‍යතාව", "සෙනෙට් සභාව නැවත ගෙන ඒමේ අවශ්‍යතාව", "පාර්ලිමේන්තු බහුතරය නිතර වෙනස් වුවද නොසැලෙන විධායකයක් තුළින් සංවර්ධනය වේගවත් කිරීම අපේක්ෂා කෙරිණි."),
    q("1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 17 වන සහ 21 වන සංශෝධන අතර පවතින ප්‍රධාන සමානකම කුමක්ද?", "දෙකෙන්ම ව්‍යවස්ථාදායක සභාව හා ස්වාධීන කොමිෂන් සභා ස්ථාපිත කිරීම", "දෙකෙන්ම ජනාධිපති ධුර කාලය වසර 8 කිරීම", "දෙකෙන්ම කේවල ඡන්ද ක්‍රමය හඳුන්වා දීම", "දෙකෙන්ම පාර්ලිමේන්තු මන්ත්‍රී සංඛ්‍යාව 150 කිරීම", "17, 19 සහ 21 සංශෝධන ස්වාධීන කොමිෂන් හා යහපාලන ව්‍යුහය ශක්තිමත් කළේය."),
    q("1978 ව්‍යවස්ථාවේ 12 වන සංශෝධනය ඉදිරිපත් කරන ලද නමුත් සිදු වූයේ කුමක්ද?", "සම්මත නොවූ කෙටුම්පතක් වූ අතර 13 වන සංශෝධනය පසුව සම්මත වීම", "ජනමත විචාරණයෙන් සම්මත වීම", "එය 1972 ව්‍යවස්ථාවට අදාළ වීම", "එමඟින් විධායක ජනාධිපති ධුරය අහෝසි වීම", "12 වන ව්‍යවස්ථා සංශෝධන කෙටුම්පත නීතිගත නොවී අතහැර දමන ලදී."),
    q("2022 21 වන සංශෝධනය යටතේ ව්‍යවස්ථාදායක සභාවේ සිටින සිවිල් සමාජ නියෝජිතයන් ගණන කීයද?", "3 දෙනෙකි", "1 දෙනෙකි", "7 දෙනෙකි", "10 දෙනෙකි", "සාමාජිකයන් 10 අතරින් 7 දෙනෙකු මන්ත්‍රීවරුන් වන අතර 3 දෙනෙකු ස්වාධීන සිවිල් නියෝජිතයෝ වෙති."),
    q("1947 සෝල්බරි ව්‍යවස්ථාවේ 'අග්‍රාණ්ඩුකාරවරයා' සහ 1972 ව්‍යවස්ථාවේ 'නාමික ජනාධිපතිවරයා' අතර ප්‍රධාන වෙනස කුමක්ද?", "1972 ජනාධිපතිවරයා බ්‍රිතාන්‍ය රැජින වෙනුවට ශ්‍රී ලංකා ජනරජයම නියෝජනය කිරීම", "1972 ජනාධිපතිවරයා විධායක බලතල සියල්ල දැරීම", "1947 අග්‍රාණ්ඩුකාරවරයා ජනතා ඡන්දයෙන් පත් වීම", "1972 ජනාධිපතිවරයා සෙනෙට් සභාවේ සභාපති වීම", "1947 අග්‍රාණ්ඩුකාරවරයා බ්‍රිතාන්‍ය කිරීටයේ නියෝජිතයා වූ අතර 1972 ජනාධිපති ස්වෛරී ජනරජයේ ප්‍රධානියා විය."),
    q("1833 කෝල්බෲක් ප්‍රතිසංස්කරණ මඟින් රාජ්‍ය පරිපාලනය සඳහා ඉංග්‍රීසි භාෂාවට ලබාදුන් තත්ත්වය කුමක්ද?", "ප්‍රධාන පරිපාලන හා අධිකරණ භාෂාව බවට පත් කිරීම", "පාසල්වල ඉගැන්වීම සම්පූර්ණයෙන් තහනම් කිරීම", "රාජ්‍ය ලේඛන සිංහලෙන් පමණක් තැබීම", "ඉංග්‍රීසි භාෂාව දෙමළ පමණක් සීමා කිරීම", "රාජ්‍ය සේවයට බඳවාගැනීමේදී ඉංග්‍රීසි අධ්‍යාපනය ප්‍රමුඛ වූ අතර පරිපාලන භාෂාව ඉංග්‍රීසි විය."),
    q("1978 ව්‍යවස්ථාවේ XI වන සංශෝධනය (11 වන සංශෝධනය - 1987) මඟින් සිදු කළ ප්‍රධාන වෙනස කුමක්ද?", "සිවිල් අභියාචනා මහාධිකරණ හා අධිකරණ බල ප්‍රදේශ විධිමත් කිරීම", "මැතිවරණ දිස්ත්‍රික්ක 22 අහෝසි කිරීම", "විධායක ජනාධිපති ධුර කාලය වසර 10 කිරීම", "ජාතික ගීය වෙනස් කිරීම", "1987 11 වන සංශෝධනය මඟින් අධිකරණ ක්‍රමය හා පළාත් මහාධිකරණ බලතල සංශෝධනය කෙරිණි."),
    q("1919 ලංකා ජාතික සංගමය බිහිවීමට පෙර සිටම ශ්‍රී ලංකාවේ ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණ ඉල්ලූ නායකයන් අතර ප්‍රමුඛයා වූයේ කවුද?", "ශ්‍රීමත් ජේම්ස් පීරිස් සහ පොන්නම්බලම් අරුණාචලම්", "ලෝඩ් ඩොනමෝර් සහ හෙන්රි මැකලම්", "රොබට් බ්‍රවුන්රිග් සහ ෆ්‍රෙඩ්රික් නෝර්ත්", "විලියම් කෝල්බෲක් සහ චාල්ස් කැමරන්", "ශ්‍රීමත් ජේම්ස් පීරිස්, එච්.ජේ.සී. පෙරේරා, අරුණාචලම් වැනි නායකයන් ව්‍යවස්ථා ප්‍රතිසංස්කරණ සඳහා පෙත්සම් ඉදිරිපත් කළහ.")
  )
}
